int Mark(string name, int value) { Print(name + value); return value; }
bool Test(int value) { Print("test" + value); return value < 4; }
int Add(int first, int second) => first + second;
void Main() {
    for (var i = Mark("init", 0); Test(i); i = Add(second: Mark("step", i), first: 1), Print("iter" + i)) {
        if (i == 1) continue;
        Print("body" + i);
        if (i == 2) break;
    }
    var sum = 0;
    for (int i = 0, j = 3; i < j; i = i + 1, j = j - 1) sum = sum + i + j;
    Print(sum);
    var count = 0;
    for (count = 0, Print("assigned"); count < 2; count = count + 1) ;
    Print(count);
    for (;;) { count = count + 1; break; }
    Print(count);
    for (; false; Print("unreachable iterator")) Print("unreachable body");
    Print("done");
}
